insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('a1b20b40-0272-481c-9b62-67e9fc0df986', '1bad5493-3244-4c53-b4b7-462a6076d5ca', $$inleiding: een bionisch oog voor blinde mensen$$,
   $$biologie-havo-2021-ii-bionisch-oog-context1.png$$,
   $$Onderzoekers in Duitsland hebben een bionisch oog ontwikkeld waardoor blinde mensen op termijn mogelijk weer kunnen zien.$$, 'inline'),
  ('5c9eb3ae-f933-44a5-a1b8-cb2664342ec9', '1bad5493-3244-4c53-b4b7-462a6076d5ca', $$retinitis pigmentosa: eerst sterven de staafjes af, later ook kegeltjes$$,
   $$biologie-havo-2021-ii-bionisch-oog-context2.png$$,
   $$Het bionische oog dat de onderzoekers ontwikkelden, werd getest bij mensen met retinitis pigmentosa. Mensen met deze aandoening worden ziend geboren, maar gedurende hun leven neemt het zicht steeds verder af doordat de zintuigcellen afsterven. In het begin sterven alleen de staafjes af, maar in een vergevorderd stadium verdwijnen ook steeds meer kegeltjes uit het netvlies.$$, 'inline'),
  ('3db7c1c9-842f-41a0-971b-88b31209cb6a', '1bad5493-3244-4c53-b4b7-462a6076d5ca', $$overerving van retinitis pigmentosa in een familie$$,
   $$biologie-havo-2021-ii-bionisch-oog-context3.png$$,
   $$Er zijn verschillende vormen van retinitis pigmentosa, die op verschillende manieren overerven. In afbeelding 1 is de overerving van retinitis pigmentosa in een familie weergegeven.$$, 'inline'),
  ('14152b3b-4d0d-4807-b39a-60db5dd9a2ba', '1bad5493-3244-4c53-b4b7-462a6076d5ca', $$afbeelding 1: stamboom met personen 1 t/m 9$$,
   $$biologie-havo-2021-ii-bionisch-oog-context4.png$$,
   $$afbeelding 1: stamboom van een familie met personen 1 t/m 9. Ouders 1 (vrouw) en 2 (man) en ouders 3 (vrouw) en 4 (man) zijn ziend; hun kinderen 5 (vrouw, retinitis pigmentosa) en 6 (man, ziend) krijgen kinderen 7 (vrouw, retinitis pigmentosa), 8 (vrouw, retinitis pigmentosa) en 9 (man, ziend). Legenda: zwart = retinitis pigmentosa, wit = ziend.$$, 'inline'),
  ('506c97c6-c1ed-4abc-841a-45cb5925d0ff', '1bad5493-3244-4c53-b4b7-462a6076d5ca', $$chip met lichtdetectors in het netvlies; afbeelding 2: netvlies met cellagen P t/m T$$,
   $$biologie-havo-2021-ii-bionisch-oog-context5.png$$,
   $$In het netvlies van drie patiënten die grotendeels blind waren door retinitis pigmentosa, werd een chip met 1500 lichtdetectors geplaatst. Als licht op een lichtdetector valt, wordt via een versterker en een elektrode een signaal afgegeven aan zenuwcellen in het netvlies. In afbeelding 2 is een deel van het netvlies met daarin een chip met vier lichtdetectors schematisch weergegeven.
afbeelding 2: schematische doorsnede van het netvlies met cellagen P, Q, R, S en T (pigmentcellen), de richting van het licht en een chip met versterker, lichtdetector en elektrode$$, 'inline'),
  ('39360c49-fbec-49bc-8226-900bcfa1e58f', '1bad5493-3244-4c53-b4b7-462a6076d5ca', $$versterker en accu van het bionische oog$$,
   $$biologie-havo-2021-ii-bionisch-oog-context6.png$$,
   $$De versterker zorgt ervoor dat het signaal van de lichtdetector sterk genoeg is om, via de zenuwcellen van het netvlies, de hersenen te bereiken. Een accu buiten het lichaam voorziet de chip van stroom via een draadje door het hoofd.$$, 'inline'),
  ('be6aca38-ac1a-4186-a7db-bbca56f05d89', '1bad5493-3244-4c53-b4b7-462a6076d5ca', $$drie uitspraken over de werking van het bionische oog$$,
   $$biologie-havo-2021-ii-bionisch-oog-context7.png$$,
   $$Over de werking van het bionische oog worden drie uitspraken gedaan:
1 Uit de informatie blijkt dat de drempelwaarde van de lichtdetectors lager is dan die van kegeltjes van een persoon zonder retinitis pigmentosa.
2 Als de elektrodes signalen afgeven, zullen in zenuwcellen van het netvlies impulsen ontstaan.
3 De beeldvorming bij de patiënt zal het beste zijn als de chip wordt aangebracht op de plaats van de gele vlek.$$, 'inline'),
  ('607f0708-ae24-40e1-981f-24c2644962a5', '1bad5493-3244-4c53-b4b7-462a6076d5ca', $$het signaal gaat via de oogzenuw naar de hersenen$$,
   $$biologie-havo-2021-ii-bionisch-oog-context8.png$$,
   $$Het signaal wordt via de oogzenuw naar de hersenen verstuurd. In de hersenen wordt de informatie verwerkt.$$, 'inline'),
  ('bef2d8e1-08da-42f1-8b82-8595d2e75426', '1bad5493-3244-4c53-b4b7-462a6076d5ca', $$test met vormen; een controleproef was onderdeel van het onderzoek$$,
   $$biologie-havo-2021-ii-bionisch-oog-context9.png$$,
   $$Om het bionische oog te testen kregen de proefpersonen vormen te zien. Uit het onderzoek werd geconcludeerd dat het bionische oog het zicht van de proefpersonen verbeterde. Een controleproef was onderdeel van dit onderzoek.$$, 'inline'),
  ('2a0015c9-db93-453e-b6a6-8513a1545d50', '7e3dd45f-4489-4f1c-8208-6b38dc6c8de5', $$inleiding: zouttolerantie van landbouwgewassen$$,
   $$biologie-havo-2021-ii-zilte-landbouw-context1.png$$,
   $$De landbouw in Nederland maakt voornamelijk gebruik van zoet water. Ecoloog Arjen de Vos van het Zilt Proefbedrijf op Texel test de zouttolerantie van gangbare landbouwgewassen. Zijn er gewassen die tegen zouter water kunnen?$$, 'inline'),
  ('96d1a3c1-2af8-4d07-8734-863962513e31', '7e3dd45f-4489-4f1c-8208-6b38dc6c8de5', $$verzilting verstoort de wateropname door de wortels$$,
   $$biologie-havo-2021-ii-zilte-landbouw-context2.png$$,
   $$Een groot deel van Nederland ligt aan de kust en heeft daardoor met binnensijpelend zeewater en brak grondwater te maken. De meeste plantensoorten zijn gevoelig voor deze verzilting. De opgeloste zout-ionen rondom de wortels verstoren de wateropname waardoor de planten uitdrogen.$$, 'inline'),
  ('af72c951-dfdb-49bd-bf34-69c78603849c', '7e3dd45f-4489-4f1c-8208-6b38dc6c8de5', $$bodemvocht rond een wortelcel bevat meer opgeloste deeltjes$$,
   $$biologie-havo-2021-ii-zilte-landbouw-context3.png$$,
   $$Bij gewassen die op zilte plaatsen groeien, bevat het bodemvocht rondom een wortelcel meer opgeloste deeltjes dan het vocht in de cel zelf. Als gevolg hiervan verandert de osmotische waarde van de wortelcellen.$$, 'inline'),
  ('49a0689e-56be-45f9-9ec6-1c83d7adb32d', '7e3dd45f-4489-4f1c-8208-6b38dc6c8de5', $$drie kenmerken van bladeren die met verdamping samenhangen$$,
   $$biologie-havo-2021-ii-zilte-landbouw-context4.png$$,
   $$Sommige droogtetolerante plantensoorten zijn ook zouttolerant. Om verdamping te kunnen beperken, hebben deze planten bepaalde aanpassingen. Drie kenmerken van bladeren zijn:
1 het aantal huidmondjes per cm²
2 de dikte van de cuticula (waslaag)
3 de bladoppervlakte ten opzichte van de bladinhoud$$, 'inline'),
  ('00e5080c-2506-41b2-90e0-0977bec6f71e', '7e3dd45f-4489-4f1c-8208-6b38dc6c8de5', $$zouttolerante planten slaan ionen op in een deel van de cel$$,
   $$biologie-havo-2021-ii-zilte-landbouw-context5.png$$,
   $$Een teveel aan zoutionen verstoort de activiteit van enzymen in plantencellen. Veel zouttolerante planten slaan opgenomen ionen op in een bepaald deel van de cel. Hierdoor worden celprocessen niet verstoord.$$, 'inline'),
  ('5e57054a-fb8e-44d7-b676-aec117561173', '7e3dd45f-4489-4f1c-8208-6b38dc6c8de5', $$wiskundig model van gewasopbrengst bij toenemende zoutconcentratie; Zmax en Z50%$$,
   $$biologie-havo-2021-ii-zilte-landbouw-context6.png$$,
   $$Arjen de Vos zoekt naar landbouwgewassen die geschikt zijn voor de zilte teelt door gewassen te kweken bij verschillende zoutconcentraties van het bodemvocht. Voor het verwerken van de gegevens gebruikt hij een wiskundig model: er is een lineaire afname van de gewasopbrengst als de zoutconcentratie van het bodemvocht een bepaalde drempelwaarde overschrijdt. Het model is weergegeven in afbeelding 1. Hierin is Zₘₐₓ de maximale zoutconcentratie waarbij er nog 100% gewasopbrengst is en Z₅₀% de zoutconcentratie waarbij de gewasopbrengst 50% is. Als maat voor de zoutconcentratie gebruikt hij de geleidbaarheid van het bodemvocht, uitgedrukt in dS/m.$$, 'inline'),
  ('3abc6305-3be7-460c-ae0b-2e032e2779ae', '7e3dd45f-4489-4f1c-8208-6b38dc6c8de5', $$afbeelding 1: relatieve opbrengst tegen zoutconcentratie met Zmax en Z50%$$,
   $$biologie-havo-2021-ii-zilte-landbouw-context7.png$$,
   $$afbeelding 1: relatieve opbrengst (%) tegen zoutconcentratie (dS/m); de opbrengst is 100% tot Zₘₐₓ en daalt daarna lineair (opbrengstdaling per 1,0 dS/m); bij Z₅₀% is de opbrengst 50%$$, 'inline'),
  ('02dd4828-e00c-4f06-a04e-ddd7f53dac9f', '7e3dd45f-4489-4f1c-8208-6b38dc6c8de5', $$Zmax en opbrengstdaling van verschillende gewassen bepaald$$,
   $$biologie-havo-2021-ii-zilte-landbouw-context8.png$$,
   $$De Vos heeft van verschillende gewassen de Zₘₐₓ (in dS/m) en de opbrengstdaling (in % per 1,0 dS/m) bepaald. Een deel van de resultaten is weergegeven in tabel 1.$$, 'inline'),
  ('e7315678-bc0c-40df-8ed0-b4cf1fa400c5', '7e3dd45f-4489-4f1c-8208-6b38dc6c8de5', $$tabel 1: Zmax en opbrengstdaling per gewas$$,
   $$biologie-havo-2021-ii-zilte-landbouw-context9.png$$,
   $$tabel 1 (Zₘₐₓ in dS/m / opbrengstdaling in % per dS/m):
aardappel, Miss Mignonne: 4 / 7
broccoli: 6 / 6
rode ui: 6 / 12
wortel, variëteit 101: 3 / 9$$, 'inline'),
  ('82b42fe5-b47c-4f1c-9cb6-d1fd8f2a86e6', '7e3dd45f-4489-4f1c-8208-6b38dc6c8de5', $$bepalen welk gewas de hoogste Z50% heeft$$,
   $$biologie-havo-2021-ii-zilte-landbouw-context10.png$$,
   $$Voor verzilte gebieden is een gewas dat nog de helft opbrengt ten opzichte van normaal, al heel aantrekkelijk. Met de gegevens uit tabel 1 is te bepalen welk van de geteste gewassen de hoogste Z₅₀% heeft.$$, 'inline'),
  ('ce182335-6492-44a1-93f2-17cc90321484', '7e3dd45f-4489-4f1c-8208-6b38dc6c8de5', $$knolletjesbacteriën en honingklaver als groenbemester; afbeelding 2: stikstofkringloop met P, Q en R$$,
   $$biologie-havo-2021-ii-zilte-landbouw-context11.png$$,
   $$Op het Zilt Proefbedrijf heeft De Vos ook meegewerkt aan een onderzoek naar de zouttolerantie van knolletjesbacteriën. Knolletjesbacteriën leven in een symbiotische relatie met vlinderbloemige planten zoals honingklaver, die als een ‘groenbemester’ wordt gebruikt. Na het onderploegen van de honingklaverplanten komen – via een reeks processen – anorganische stikstofverbindingen in de bodem. Deze verbindingen kunnen door het volgend gewas opgenomen worden. Deze processen zijn weergegeven in afbeelding 2.
afbeelding 2: schema met honingklaver en een volgend gewas. Stikstofgas (N₂) diffundeert de bodem in; in de wortelknolletjes met knolletjesbacteriën wordt N₂ via pijl P omgezet in een organische stikstofverbinding. Na onderploegen en afbraak wordt de organische stikstofverbinding via pijl Q omgezet in ammonium (NH₄⁺) en via pijl R in nitraat (NO₃⁻), dat door het volgend gewas wordt opgenomen.$$, 'inline'),
  ('c85d7675-7595-430b-a82f-f8103d36ae30', '7e3dd45f-4489-4f1c-8208-6b38dc6c8de5', $$in afbeelding 2 zijn met P, Q en R processen uit de stikstofkringloop aangegeven$$,
   $$biologie-havo-2021-ii-zilte-landbouw-context12.png$$,
   $$In het schema in afbeelding 2 zijn met de pijlen P, Q en R processen uit de stikstofkringloop aangegeven waarbij stikstofverbindingen worden omgezet.$$, 'inline'),
  ('859abdd6-e5fc-4fd9-b14f-6db8e03424b9', '7e3dd45f-4489-4f1c-8208-6b38dc6c8de5', $$kunstmest als alternatief voor groenbemesting$$,
   $$biologie-havo-2021-ii-zilte-landbouw-context13.png$$,
   $$Naast groenbemesting kan er ook gekozen worden voor het gebruik van kunstmest. Kunstmest is een mengsel van mineralen dat in de fabriek wordt gemaakt, onder andere uit gesteenten.$$, 'inline'),
  ('4e566e9a-c7ff-4c0e-aee2-25d08daea3d9', '7e3dd45f-4489-4f1c-8208-6b38dc6c8de5', $$proef met honingklaver bij vijf zoutconcentraties$$,
   $$biologie-havo-2021-ii-zilte-landbouw-context14.png$$,
   $$Op het Zilt Proefbedrijf werd op proefveldjes honingklaver gezaaid. Elk veldje werd bevloeid met een bepaalde zoutoplossing. Er werden vijf verschillende zoutconcentraties getest. De zoutoplossingen werden gemaakt door regenwater (0 dS/m) en Waddenzeewater (35 dS/m) in verschillende verhoudingen te mengen. Na vier maanden werd de honingklaver geoogst en werd de biomassa van de planten bepaald. Ook werd van een stukje van de wortels het stikstofgehalte bepaald. De onderzoekers bepaalden welk percentage van de stikstof afkomstig is van stikstofgas uit de lucht aan de hand van de samenstelling van de stikstofisotopen. De resultaten zijn weergegeven in afbeelding 3.$$, 'inline'),
  ('03397f7f-4d6a-4a73-a759-9c55bac76b8b', '7e3dd45f-4489-4f1c-8208-6b38dc6c8de5', $$afbeelding 3: biomassa en percentage stikstof uit de lucht per zoutconcentratie$$,
   $$biologie-havo-2021-ii-zilte-landbouw-context15.png$$,
   $$afbeelding 3: twee staafdiagrammen tegen de zoutconcentratie (1,7; 4; 8; 12 en 16 dS/m): links de gemiddelde biomassa (g), die afneemt van ongeveer 200 g naar ongeveer 40 g; rechts de stikstof in de plant afkomstig uit de lucht (% van totaal stikstof), die bij alle concentraties ongeveer 95-100% is$$, 'inline'),
  ('61ecf4ec-f38f-4621-8a9f-ff2cf8f07c5e', '7e3dd45f-4489-4f1c-8208-6b38dc6c8de5', $$drie uitspraken naar aanleiding van de resultaten$$,
   $$biologie-havo-2021-ii-zilte-landbouw-context16.png$$,
   $$Naar aanleiding van de resultaten van de proef worden drie uitspraken gedaan:
1 Een hogere zoutconcentratie verhoogt de dissimilatie van honingklaver.
2 Honingklaver neemt stikstof vooral op via de bladeren.
3 De activiteit van knolletjesbacteriën is de beperkende factor voor de groei van honingklaver in zilte omstandigheden.$$, 'inline'),
  ('4022af54-99a0-406c-9168-b2402243af6a', '3063eccd-5156-496e-89e0-8ed1ef400664', $$inleiding: beklimming van de Mont Blanc (afbeelding 1)$$,
   $$biologie-havo-2021-ii-de-mont-blanc-adembenemend-context1.png$$,
   $$Anna gaat met een groep klimmers onder leiding van een ervaren gids de Mont Blanc (afbeelding 1) beklimmen. Om de kans op hoogteziekte te verkleinen, beklimmen ze eerst enkele lagere bergen in de omgeving.
afbeelding 1: foto van een klimmer op een besneeuwde bergkam$$, 'inline'),
  ('29808b9d-b052-4a97-9b65-632a891bb93d', '3063eccd-5156-496e-89e0-8ed1ef400664', $$hoogteziekte door minder zuurstof; Anna hijgt$$,
   $$biologie-havo-2021-ii-de-mont-blanc-adembenemend-context2.png$$,
   $$Hoogteziekte ontstaat doordat lucht op grote hoogte minder zuurstof bevat dan lucht op zeeniveau. Hierdoor wordt minder zuurstof ingeademd en daalt de hoeveelheid zuurstof in het bloed. Klachten bij milde hoogteziekte zijn hoofdpijn, kortademigheid en misselijkheid. Bij ernstige hoogteziekte is er sprake van long- en hersenoedeem, wat levensbedreigend kan zijn. Voor de beklimming van de Mont Blanc wordt een aantal dagen uitgetrokken. Na twee dagen bereikt de groep een hoogte van 3835 meter. Anna merkt dat ze hijgt: ze ademt veel vaker en dieper in en uit dan normaal, zelfs als ze zich nauwelijks inspant.$$, 'inline'),
  ('2132a855-159c-492e-8be9-bc28085d6285', '3063eccd-5156-496e-89e0-8ed1ef400664', $$vijf spiergroepen betrokken bij in- en uitademing$$,
   $$biologie-havo-2021-ii-de-mont-blanc-adembenemend-context3.png$$,
   $$In afbeelding 2 zijn vijf spiergroepen getekend die betrokken zijn bij de inademing of bij de uitademing. Bij 1, 2 en 3 is met pijlen aangegeven in welke richting de ribben bewegen als de betreffende spiergroepen samentrekken. Bij 4 en 5 is met pijlen aangegeven in welke richting het middenrif beweegt als de betreffende spiergroepen samentrekken.$$, 'inline'),
  ('520998a8-8fd8-400e-ac27-c058bf397820', '3063eccd-5156-496e-89e0-8ed1ef400664', $$afbeelding 2: borstkas met spiergroepen 1 t/m 5$$,
   $$biologie-havo-2021-ii-de-mont-blanc-adembenemend-context4.png$$,
   $$afbeelding 2: borstkas met vijf spiergroepen: 1 halsspieren, 2 buitenste tussenribspieren, 3 binnenste tussenribspieren, 4 middenrifspieren, 5 buikspieren$$, 'inline'),
  ('73b418a7-2f2a-4094-838b-788185a82a4f', '3063eccd-5156-496e-89e0-8ed1ef400664', $$ADH beïnvloedt het watertransport in de nieren$$,
   $$biologie-havo-2021-ii-de-mont-blanc-adembenemend-context5.png$$,
   $$Door het hijgen verliest Anna veel water. De hypofyse reageert op watertekort door afgifte van het hormoon ADH. ADH beïnvloedt het watertransport in de nieren.$$, 'inline'),
  ('ee44d69b-a3a2-449e-9f05-cc662f823914', '3063eccd-5156-496e-89e0-8ed1ef400664', $$longoedeem en de diffusiesnelheid van zuurstof$$,
   $$biologie-havo-2021-ii-de-mont-blanc-adembenemend-context6.png$$,
   $$Een symptoom van hoogteziekte is longoedeem: bloedvaten in de longen vernauwen, waardoor de bloeddruk stijgt. Hierdoor gaan haarvaten vocht lekken waardoor er vocht in het longweefsel en in de longblaasjes komt. Dit beïnvloedt de diffusie van zuurstof vanuit de longblaasjes naar de haarvaten. De diffusiesnelheid V van zuurstof vanuit de longblaasjes naar het bloed kan met de volgende formule worden bepaald:$$, 'inline'),
  ('ea1f16fd-7cb0-4712-9f54-41b2be68126a', '3063eccd-5156-496e-89e0-8ed1ef400664', $$formule voor de diffusiesnelheid V$$,
   $$biologie-havo-2021-ii-de-mont-blanc-adembenemend-context7.png$$,
   $$V = D · A · (c₂ − c₁) / x
− D is de diffusieconstante
− A is de oppervlakte van de longblaasjes
− (c₂ − c₁) is het verschil in zuurstofconcentratie tussen bloed en lucht
− x is de diffusie-afstand$$, 'inline'),
  ('9f53e01f-9ae2-4aa8-bdb7-02514981c028', '3063eccd-5156-496e-89e0-8ed1ef400664', $$bij longoedeem verandert de diffusie-afstand$$,
   $$biologie-havo-2021-ii-de-mont-blanc-adembenemend-context8.png$$,
   $$Bij longoedeem verandert de diffusie-afstand en daardoor de diffusiesnelheid van zuurstof.$$, 'inline'),
  ('fa5d3c1c-73cd-417f-b04b-40dc98e74acb', '3063eccd-5156-496e-89e0-8ed1ef400664', $$medicijn houdt CO₂-concentratie hoog; regeling van de longventilatie$$,
   $$biologie-havo-2021-ii-de-mont-blanc-adembenemend-context9.png$$,
   $$Enkele klimmers uit Anna''s groep gebruiken een medicijn dat de kans op hoogteziekte verkleint. Dit medicijn bevat een stof die ervoor zorgt dat de CO₂-concentratie in het bloed hoog blijft. Hierdoor wordt de longventilatie beïnvloed. Bij de regeling van de longventilatie zijn het ademcentrum in de hersenstam, ademhalingsspieren en chemoreceptoren betrokken.$$, 'inline'),
  ('f41b0c7e-646c-4e98-a73a-f2c17ae8d1f7', '3063eccd-5156-496e-89e0-8ed1ef400664', $$regeling van de longventilatie als onvolledige regelkring$$,
   $$biologie-havo-2021-ii-de-mont-blanc-adembenemend-context10.png$$,
   $$In afbeelding 3 is de regeling van de longventilatie weergegeven als een regelkring. Het schema is nog niet compleet.$$, 'inline'),
  ('636a8843-123f-4393-abf5-a0e84c70cc31', '3063eccd-5156-496e-89e0-8ed1ef400664', $$afbeelding 3: onvolledig schema van de regelkring longventilatie$$,
   $$biologie-havo-2021-ii-de-mont-blanc-adembenemend-context11.png$$,
   $$afbeelding 3: onvolledig schema van de regelkring: CO₂-concentratie van het bloed → (cirkel) → leeg vak → (cirkel) → leeg vak → (cirkel) → leeg vak → (cirkel) → ademhalingsfrequentie → (cirkel) → terug naar CO₂-concentratie van het bloed$$, 'inline'),
  ('eff5b755-a91b-456c-b166-8469109c49db', '3063eccd-5156-496e-89e0-8ed1ef400664', $$in de uitwerkbijlage is het schema nogmaals afgebeeld$$,
   $$biologie-havo-2021-ii-de-mont-blanc-adembenemend-context12.png$$,
   $$In de uitwerkbijlage is het schema nogmaals afgebeeld.$$, 'inline'),
  ('65f0bcbc-2d28-4c36-8832-ae8e20cdbe07', '3063eccd-5156-496e-89e0-8ed1ef400664', $$dopamine zorgt voor impulsoverdracht tussen zenuwcellen$$,
   $$biologie-havo-2021-ii-de-mont-blanc-adembenemend-context13.png$$,
   $$Anna bereikt zonder problemen de top. Door het vrijkomen van dopamine in haar hersenen ervaart ze een gelukkig gevoel. Dopamine zorgt voor impulsoverdracht tussen zenuwcellen in de hersenen.$$, 'inline'),
  ('6aac4aeb-9bbb-497f-b954-48059c970891', '3063eccd-5156-496e-89e0-8ed1ef400664', $$uitwerkbijlage vraag 17: in te vullen regelkring longventilatie$$,
   $$biologie-havo-2021-ii-de-mont-blanc-adembenemend-context14.png$$,
   $$17
uitwerkbijlage: onvolledig schema van de regelkring longventilatie met drie lege vakken en vijf lege cirkels tussen CO₂-concentratie van het bloed en ademhalingsfrequentie$$, 'uitwerkbijlage'),
  ('9b46da1f-37f5-4982-ba95-03114da26c7b', '7964e52b-cd01-4392-8af4-cc4334b8c151', $$inleiding: genetisch gemodificeerde mug tegen malaria$$,
   $$biologie-havo-2021-ii-modificatie-van-malariamuggen-context1.png$$,
   $$Elk jaar overlijdt bijna een miljoen mensen aan malaria. Een Amerikaanse onderzoeksgroep heeft nu een genetisch gemodificeerde mug ontwikkeld die de verspreiding van malaria misschien kan stoppen.$$, 'inline'),
  ('807d8c12-6b83-4846-8b7a-2342223d0e1e', '7964e52b-cd01-4392-8af4-cc4334b8c151', $$malariaparasiet, malariamug en de mens$$,
   $$biologie-havo-2021-ii-modificatie-van-malariamuggen-context2.png$$,
   $$De ziekte malaria wordt veroorzaakt door de malariaparasiet (Plasmodium sp.), een eencellig organisme. Voor zijn verspreiding is de malariaparasiet afhankelijk van malariamuggen (Anopheles sp.). Een malariamug kan de parasiet overbrengen van een besmet persoon naar een niet-besmet persoon. Voor de mens is de malariaparasiet een parasiet.$$, 'inline'),
  ('cc248a6d-da93-4729-a183-1ae099b8b37b', '7964e52b-cd01-4392-8af4-cc4334b8c151', $$de relatie tussen malariamug en malariaparasiet wordt commensalisme genoemd$$,
   $$biologie-havo-2021-ii-modificatie-van-malariamuggen-context3.png$$,
   $$De relatie tussen de malariamug en de malariaparasiet wordt commensalisme genoemd.$$, 'inline'),
  ('128d5112-69d9-4d19-ba26-3815d74ce5d1', '7964e52b-cd01-4392-8af4-cc4334b8c151', $$in afbeelding 1 is de malariaparasiet schematisch weergegeven$$,
   $$biologie-havo-2021-ii-modificatie-van-malariamuggen-context4.png$$,
   $$In afbeelding 1 is de malariaparasiet schematisch weergegeven.$$, 'inline'),
  ('c4b3e023-cf2e-4995-807c-47475ed2170c', '7964e52b-cd01-4392-8af4-cc4334b8c151', $$afbeelding 1: schematische tekening van de malariaparasiet$$,
   $$biologie-havo-2021-ii-modificatie-van-malariamuggen-context5.png$$,
   $$afbeelding 1: schematische tekening van de malariaparasiet met kern, ribosoom, endoplasmatisch reticulum, golgi-apparaat, mitochondrium en celmembraan$$, 'inline'),
  ('13d67796-29d2-4517-b200-c823618e7c17', '7964e52b-cd01-4392-8af4-cc4334b8c151', $$resistentie-gen en modificatie-genen; kruising gemodificeerd mannetje met gewoon vrouwtje$$,
   $$biologie-havo-2021-ii-modificatie-van-malariamuggen-context6.png$$,
   $$Om te voorkomen dat malariamuggen de malariaparasieten verspreiden, hebben de Amerikaanse onderzoekers een bepaald gen (resistentie-gen) ingebouwd in het DNA van de mug. Dit resistentie-gen zorgt ervoor dat de malariaparasiet zich niet meer kan ontwikkelen in de mug. De onderzoekers gebruikten hiervoor een nieuwe methode: een resistentie-gen wordt samen met enkele modificatie-genen ingebracht in het DNA van eicellen van de mug. Na bevruchting van de eicel zorgen de modificatie-genen ervoor dat het resistentie-gen en de modificatie-genen naar het homologe chromosoom worden gekopieerd. Een heterozygote cel wordt hierdoor homozygoot voor deze genen. Als de gemodificeerde malariamuggen worden losgelaten in de populatie gewone malariamuggen, zullen er kruisingen plaatsvinden. In afbeelding 2 is schematisch de kruising weergegeven van een gemodificeerd mannetje met een gewoon vrouwtje.$$, 'inline'),
  ('f3f0fd5c-c0bf-444f-a38c-682eb47a9455', '7964e52b-cd01-4392-8af4-cc4334b8c151', $$afbeelding 2: kruisingsschema met in te vullen genotypen$$,
   $$biologie-havo-2021-ii-modificatie-van-malariamuggen-context7.png$$,
   $$afbeelding 2: kruisingsschema: gemodificeerde mug (♂, genotype RR) en gewone mug (♀, genotype rr); genotype zaadcellen: ......; genotype eicellen: ......; genotype zygoten direct na bevruchting: ......; na modificatie door modificatiegenen: genotype nakomelingen: ......; daarna genotype zaadcellen: ...... of genotype eicellen: ......
In de uitwerkbijlage vind je dezelfde afbeelding.$$, 'inline'),
  ('befdd406-7ef7-4486-b0fb-3ade70bd0949', '7964e52b-cd01-4392-8af4-cc4334b8c151', $$malariamuggen worden met deze methode niet uitgeroeid$$,
   $$biologie-havo-2021-ii-modificatie-van-malariamuggen-context8.png$$,
   $$Door de methode met de gemodificeerde malariamuggen te gebruiken ter bestrijding van malaria, worden malariamuggen niet uitgeroeid.$$, 'inline'),
  ('3d697ff6-ee94-4703-94c0-6d027461315c', '7964e52b-cd01-4392-8af4-cc4334b8c151', $$uitwerkbijlage vraag 21: in te vullen kruisingsschema$$,
   $$biologie-havo-2021-ii-modificatie-van-malariamuggen-context9.png$$,
   $$21
uitwerkbijlage: kruisingsschema met gemodificeerde mug (♂, RR) en gewone mug (♀, rr) en lege invulplaatsen voor de genotypen van zaadcellen, eicellen, zygoten, nakomelingen en hun geslachtscellen$$, 'uitwerkbijlage'),
  ('e0da5812-12e2-48b9-9584-95272df406a2', '92a3eaa8-87ed-485f-8fe7-347d8c401811', $$inleiding: niet alle hommelsoorten kunnen de klimaatverandering bijhouden$$,
   $$biologie-havo-2021-ii-klimaat-en-hommel-evolutie-context1.png$$,
   $$Het klimaat heeft een grote rol gespeeld bij de evolutie van hommels, maar het lijkt erop dat niet alle hommelsoorten de huidige klimaatverandering kunnen bijhouden.$$, 'inline'),
  ('f739b0b4-85a2-45af-b34e-b2bf5a6a395c', '92a3eaa8-87ed-485f-8fe7-347d8c401811', $$hommels (afbeelding 1) zijn aangepast aan koude omstandigheden$$,
   $$biologie-havo-2021-ii-klimaat-en-hommel-evolutie-context2.png$$,
   $$Hommels (afbeelding 1) zijn insecten die leven van nectar en stuifmeel. Ze spelen een belangrijke rol bij de bestuiving van bepaalde plantensoorten. Hommels hebben een aantal eigenschappen waardoor ze aangepast zijn aan koude omstandigheden. De hommel kan zijn lichaamstemperatuur verhogen door het trillen van de borstspieren, zonder dat de vleugels meebewegen. Hij kan zo een lichaamstemperatuur tot 32 °C bereiken, zelfs bij een omgevingstemperatuur van rond het vriespunt. Daarnaast is het lichaam van de hommel behaard.
afbeelding 1: foto van een hommel$$, 'inline'),
  ('447deb6e-9f80-4a5d-81e2-0864be642726', '92a3eaa8-87ed-485f-8fe7-347d8c401811', $$in afbeelding 2 zijn vier diagrammen weergegeven$$,
   $$biologie-havo-2021-ii-klimaat-en-hommel-evolutie-context3.png$$,
   $$In afbeelding 2 zijn vier diagrammen weergegeven.$$, 'inline'),
  ('31c314b0-ccca-4412-b4ca-27c52d3fdf57', '92a3eaa8-87ed-485f-8fe7-347d8c401811', $$afbeelding 2: vier diagrammen energieverbruik tegen omgevingstemperatuur$$,
   $$biologie-havo-2021-ii-klimaat-en-hommel-evolutie-context4.png$$,
   $$afbeelding 2: vier diagrammen van het energieverbruik tegen de omgevingstemperatuur (0-15 °C): diagram 1 stijgend, diagram 2 constant, diagram 3 dalend, diagram 4 eerst stijgend en daarna dalend$$, 'inline'),
  ('9c6c1e7a-c00f-4fe0-8b23-4e2449b6050e', '92a3eaa8-87ed-485f-8fe7-347d8c401811', $$hommel is groter en dikker dan een honingbij$$,
   $$biologie-havo-2021-ii-klimaat-en-hommel-evolutie-context5.png$$,
   $$Doordat een hommel groter en dikker is dan een honingbij, kan de hommel zijn warmte beter vasthouden dan een honingbij.$$, 'inline'),
  ('1b7a646a-35cf-42b5-a157-fd73364dff0b', '92a3eaa8-87ed-485f-8fe7-347d8c401811', $$hommelsoorten verdwijnen uit hun zuidelijkste leefgebieden$$,
   $$biologie-havo-2021-ii-klimaat-en-hommel-evolutie-context6.png$$,
   $$Juist door zijn evolutionaire aanpassing aan lagere temperaturen komt de hommel nu in de problemen. Onderzoekers ontdekten dat hommelsoorten verdwijnen uit hun zuidelijkste leefgebieden. Zowel in Noord-Amerika als in Europa is de zuidgrens van het leefgebied van sommige hommel- soorten bijna 300 kilometer naar het noorden opgeschoven. Noordelijk is de grens voor de meeste soorten op deze continenten stabiel gebleven. Het leefgebied van de hommelsoorten is dus een stuk kleiner geworden.$$, 'inline'),
  ('77adcca6-c6f6-4b2c-b23a-c7a7d083d791', '92a3eaa8-87ed-485f-8fe7-347d8c401811', $$andere abiotische en biotische factoren voor het verdwijnen van hommels$$,
   $$biologie-havo-2021-ii-klimaat-en-hommel-evolutie-context7.png$$,
   $$De onderzoekers hebben ook nagedacht over andere abiotische en biotische factoren die de verdwijning van de hommels zouden kunnen veroorzaken, zoals het verdwijnen van bepaalde plantensoorten.$$, 'inline'),
  ('a45efb1c-2c32-449b-ad9e-7434fc2e6909', '92a3eaa8-87ed-485f-8fe7-347d8c401811', $$aardhommel breidt zijn leefgebied uit; korte generatietijd$$,
   $$biologie-havo-2021-ii-klimaat-en-hommel-evolutie-context8.png$$,
   $$De aardhommel (Bombus terrestris) heeft de noordgrens van zijn leefgebied wél in noordwaartse richting uitgebreid. Door de klimaatverandering was hiervoor geen aanpassing in temperatuurtolerantie nodig, maar wel aanpassing aan andere omstandigheden zoals de te bezoeken plantensoorten. Het lijkt erop dat deze hommelsoort door de korte generatietijd (de tijd die één levenscyclus duurt) voldoende gelegenheid heeft gekregen om zijn voedselzoekgedrag aan te passen.$$, 'inline'),
  ('f4fc8c57-b614-4660-bd31-7529f32821d7', '92a3eaa8-87ed-485f-8fe7-347d8c401811', $$zuigsnuit van Bombus balteatus korter geworden; afbeelding 3$$,
   $$biologie-havo-2021-ii-klimaat-en-hommel-evolutie-context9.png$$,
   $$Door hun lange zuigsnuit kunnen hommels nectar halen uit bloemen met lange bloembuizen (afbeelding 3). De Amerikaanse hommelsoort Bombus balteatus komt voor in de hogere gedeeltes van de Rocky Mountains. In die gebieden is door klimaatverandering het aantal bloeiende planten afgenomen. Uit onderzoek blijkt dat de gemiddelde lengte van de zuigsnuit van Bombus balteatus daar met 24% is afgenomen in de afgelopen 50 jaar. Hommels met een kortere zuigsnuit kunnen makkelijker nectar opnemen uit bloemen van plantensoorten met korte bloembuizen. Hierdoor kunnen deze hommels veel meer plantensoorten bezoeken. Plantensoorten met een lange bloembuis kunnen ze echter niet meer bezoeken.
afbeelding 3: foto van een hommel bij een bloem met een lange bloembuis$$, 'inline'),
  ('49a11ba7-d767-42d3-81f0-9ece779c2283', 'f0353416-377a-4024-a21d-edf5828157f9', $$inleiding: zwemmers met jeukende bultjes$$,
   $$biologie-havo-2021-ii-zwemmersjeuk-context1.png$$,
   $$Het is al een paar dagen boven de 25 °C en er wordt volop gezwommen in recreatieplas de Polderpoel. Aan het einde van de dag hebben enkele zwemmers rode bultjes die flink jeuken. Beheerder Jack schrikt: zit er zwemmersjeuk in zijn zwemwater?$$, 'inline'),
  ('9ab56c90-eccf-41c8-b392-673187dc4b42', 'f0353416-377a-4024-a21d-edf5828157f9', $$levenscyclus van de platworm Trichobilharzia ocellata (afbeelding 1)$$,
   $$biologie-havo-2021-ii-zwemmersjeuk-context2.png$$,
   $$Zwemmersjeuk wordt veroorzaakt door verschillende parasitaire platwormen van het geslacht Trichobilharzia die tijdens hun levenscyclus twee verschillende gastheren infecteren. Een van deze soorten, Trichobilharzia ocellata, ontwikkelt zich in de longen van watervogels tot een volwassen platworm (afbeelding 1). Via de bloedsomloop gaat de platworm naar het weefsel van de dunne darm om eitjes te leggen (1). Deze eitjes ontwikkelen zich in het darmweefsel tot larven. Via de ontlasting komen de larven in het water terecht (2) en dringen een waterslak binnen (3). In de waterslak ontwikkelen ze zich tot een cercarie (het tweede larvestadium). De cercariën verlaten de slak (4) en gaan in het water op zoek naar een watervogel (1). Ze dringen door de huid van de poten naar binnen, komen in de bloedsomloop en bereiken zo het longweefsel. Cercariën proberen ook de huid van zwemmende mensen binnen te dringen (5). Deze is voor hen echter ondoordringbaar. De cercarie sterft, maar veroorzaakt wel een jeukend bultje.
afbeelding 1: levenscyclus met volwassen worm in de watervogel (1), larven (2), waterslak (3), cercariën (4) en een zwemmende mens (5)$$, 'inline'),
  ('6c108b75-e0c7-4da8-9603-a5daffb4e6e3', 'f0353416-377a-4024-a21d-edf5828157f9', $$cercarie dringt de huid van een watervogel binnen; dubbele bloedsomloop$$,
   $$biologie-havo-2021-ii-zwemmersjeuk-context3.png$$,
   $$Een cercarie van de soort Trichobilharzia ocellata dringt de huid van de poten van een watervogel binnen. Vogels hebben een dubbele bloedsomloop met dezelfde bouw als bij de mens.$$, 'inline'),
  ('c2790088-4639-4e5b-973a-7885dceb8095', 'f0353416-377a-4024-a21d-edf5828157f9', $$larven beschadigen het darmweefsel; groeiachterstand$$,
   $$biologie-havo-2021-ii-zwemmersjeuk-context4.png$$,
   $$De larven beschadigen het darmweefsel van de watervogel. Watervogels met veel Trichobilharzia ocellata hebben daardoor soms een groeiachterstand.$$, 'inline'),
  ('e83ceb64-e88b-4641-8556-e1928a212480', 'f0353416-377a-4024-a21d-edf5828157f9', $$eDNA-onderzoek naar de aanwezigheid van de platworm$$,
   $$biologie-havo-2021-ii-zwemmersjeuk-context5.png$$,
   $$Jack wil weten of zijn zwemwater besmet is met Trichobilharzia ocellata. Cercariën zijn echter niet met het blote oog te zien. Hij vult een paar jampotjes met water van plaatsen waar zich waterslakken bevinden en brengt ze naar een ecologisch onderzoeksbureau. Het bureau onderzoekt de watermonsters op DNA-sporen (eDNA). Doordat alle in het water voorkomende organismen DNA-sporen achterlaten, kan hiermee de aanwezigheid van een soort worden aangetoond. Dit onderzoek heeft een hoge betrouwbaarheid en een hoge validiteit.$$, 'inline'),
  ('e77c507b-e62d-4694-868e-64dca17eef0f', 'f0353416-377a-4024-a21d-edf5828157f9', $$resultaat positief; afbeelding 2 geeft een voedselweb$$,
   $$biologie-havo-2021-ii-zwemmersjeuk-context6.png$$,
   $$Het resultaat van het onderzoek is positief: Trichobilharzia ocellata is in het zwemwater aanwezig. Afbeelding 2 geeft een vereenvoudigd voedselweb in de recreatieplas weer.$$, 'inline'),
  ('876c0a19-cd1f-45e4-ad00-3fabd52ac1ee', 'f0353416-377a-4024-a21d-edf5828157f9', $$afbeelding 2: voedselweb in de recreatieplas$$,
   $$biologie-havo-2021-ii-zwemmersjeuk-context7.png$$,
   $$afbeelding 2: voedselweb met waterplanten, algen, larve van kokerjuffer, kikkervisje, waterslak, muggenlarve, watervlo, blankvoorn, stekelbaars en baars; pijlen geven aan wie door wie gegeten wordt (de blankvoorn eet onder andere waterslakken en wordt gegeten door de baars)$$, 'inline'),
  ('ebb65dbf-665e-49d1-a26a-bb0988041d1e', 'f0353416-377a-4024-a21d-edf5828157f9', $$voorstel om extra blankvoorns uit te zetten tegen de slakken$$,
   $$biologie-havo-2021-ii-zwemmersjeuk-context8.png$$,
   $$Na bestudering van het voedselweb (afbeelding 2) stelt Jack voor om extra blankvoorns uit te zetten, om hiermee de slakken te bestrijden. De ecoloog van het onderzoeksbureau betwijfelt of dit voldoende is omdat de blankvoorn ook andere organismen eet.$$, 'inline'),
  ('b73b3f7b-2d8e-442d-9ed2-373c56ba14c1', 'e6071f53-d1b3-46cb-aabe-531f3db950d5', $$inleiding: de Amerikaanse vogelkers is een moeilijk uit te roeien exoot$$,
   $$biologie-havo-2021-ii-amerikaanse-vogelkers-context1.png$$,
   $$De Amerikaanse vogelkers is een exoot in Nederland. De soort wordt door vrijwilligers bestreden, maar blijkt lastig uit te roeien.$$, 'inline'),
  ('4d16da3d-03af-444b-9016-a30396ac1935', 'e6071f53-d1b3-46cb-aabe-531f3db950d5', $$Amerikaanse vogelkers (afbeelding 1) aangeplant op voedselarme gronden$$,
   $$biologie-havo-2021-ii-amerikaanse-vogelkers-context2.png$$,
   $$De Amerikaanse vogelkers (Prunus serotina, afbeelding 1) is een struikachtige boomsoort waarvan de vruchten worden gegeten door vogels en zoogdieren. Oorspronkelijk komt de plant voor in Noord-Amerika. Amerikaanse vogelkersen werden in het midden van de vorige eeuw samen met dennen en lariksen aangeplant op voedselarme zandvlakten en heidegebieden in Nederland om deze gebieden tot bossen om te vormen.
afbeelding 1: foto van takken van de Amerikaanse vogelkers met bessen$$, 'inline'),
  ('63c30349-e5c1-4835-8819-52796f5d790f', 'e6071f53-d1b3-46cb-aabe-531f3db950d5', $$breed tolerantiegebied voor abiotische factoren$$,
   $$biologie-havo-2021-ii-amerikaanse-vogelkers-context3.png$$,
   $$De Amerikaanse vogelkers kan goed groeien op verschillende bodemtypes doordat de soort een breed tolerantiegebied heeft voor bepaalde abiotische factoren.$$, 'inline'),
  ('c90bb80d-1608-4a09-9a96-45a7802be7a0', 'e6071f53-d1b3-46cb-aabe-531f3db950d5', $$grote genetische variatie in de populatie$$,
   $$biologie-havo-2021-ii-amerikaanse-vogelkers-context4.png$$,
   $$De populatie Amerikaanse vogelkers heeft een grote genetische variatie.$$, 'inline'),
  ('378966ee-8ed6-49c1-ad83-1c173303c2d0', 'e6071f53-d1b3-46cb-aabe-531f3db950d5', $$bestrijding met loodglansschimmel (afbeelding 2)$$,
   $$biologie-havo-2021-ii-amerikaanse-vogelkers-context5.png$$,
   $$De Amerikaanse vogelkers is een sterke concurrent in de struiklaag van bossen. Sommige ecologen vermoeden dat hij inheemse soorten wegconcurreert. Daarom wordt geprobeerd de plant uit te roeien in Nederland. Groepen vrijwilligers verwijderen Amerikaanse vogelkersen door het afzagen van de struiken en het uittrekken van de zaailingen. Om te voorkomen dat afgezaagde vogelkersstruiken weer verder groeien, kan op de afgezaagde stammen van de planten een oplossing met loodglansschimmel gesmeerd worden (afbeelding 2). De loodglansschimmel groeit via het hout van de stam het wortelstelsel van de vogelkers in. Als de plant vanuit de stam nieuwe takken en bladeren vormt, komen giftige stofwisselingsproducten van de schimmel via de anorganische sapstroom in de takken en bladeren terecht. De bladeren krijgen daardoor een zilverachtige kleur en sterven af. Door het afsterven van de bladeren sterven de wortels uiteindelijk ook af.
afbeelding 2: tekening van een afgezaagde stam die met een kwast wordt ingesmeerd$$, 'inline'),
  ('0e7b60db-b414-461d-9d52-63de9c0e51ef', 'e6071f53-d1b3-46cb-aabe-531f3db950d5', $$doden of verwijderen van alle planten is niet voldoende$$,
   $$biologie-havo-2021-ii-amerikaanse-vogelkers-context6.png$$,
   $$Zelfs als alle Amerikaanse vogelkersen worden gedood of verwijderd, is dat toch vaak niet voldoende om de soort in een gebied uit te roeien.$$, 'inline'),
  ('8306d30a-d60e-48f6-a4ae-89e92bb69ab8', 'e6071f53-d1b3-46cb-aabe-531f3db950d5', $$begrazing door schapen heeft ecologische nadelen$$,
   $$biologie-havo-2021-ii-amerikaanse-vogelkers-context7.png$$,
   $$Door begrazing met schapen kan de bedekkingsgraad van de Amerikaanse vogelkers laag gehouden worden. In vergelijking met het uittrekken van de planten heeft het begrazen door schapen echter ook ecologische nadelen voor het gebied.$$, 'inline'),
  ('02c26635-833e-4c20-86bf-3d0697554448', 'e6071f53-d1b3-46cb-aabe-531f3db950d5', $$vijfstippelig struikhaantje en keuze-experiment (afbeelding 3 en 4)$$,
   $$biologie-havo-2021-ii-amerikaanse-vogelkers-context8.png$$,
   $$Ondanks alle pogingen is de Amerikaanse vogelkers nog steeds aanwezig in Nederland. Onderzoek van Naturalis laat echter zien dat er in de afgelopen eeuw steeds meer vraat is aan de Amerikaanse vogelkers. Op de aangevreten planten werden veel larven van het vijfstippelig struikhaantje (Gonioctena quinquepunctata, afbeelding 3) gevonden die voorheen voornamelijk werden aangetroffen op de gewone lijsterbes (Sorbus aucuparia). In een gebied waar zowel de Amerikaanse vogelkers als de gewone lijsterbes voorkomen, verzamelden de onderzoekers larven van het vijfstippelig struikhaantje op beide plantensoorten. Vervolgens werd een keuze-experiment uitgevoerd.
afbeelding 3: foto van een larve van het vijfstippelig struikhaantje
Bij dit keuze-experiment werd een aantal flessen gevuld met elk twee takken: een tak van de Amerikaanse vogelkers en een lijsterbes-tak. Vervolgens zetten de onderzoekers de larven op de stop van de flessen (bij de pijl in afbeelding 4). Dit waren óf larven die waren gevangen op de Amerikaanse vogelkers óf larven die waren gevangen op de gewone lijsterbes. De volgende dag werd gekeken waar de larven zich bevonden.
afbeelding 4: fles met water met een tak van de Amerikaanse vogelkers en een lijsterbes-tak; een pijl wijst naar de stop
Naar aanleiding van de resultaten concludeerden de onderzoekers dat de larven die verzameld waren op de gewone lijsterbes duidelijk voorkeur hadden voor de gewone lijsterbes, en dat de larven die verzameld waren op de Amerikaanse vogelkers géén duidelijke voorkeur hadden voor een van de twee soorten.$$, 'inline'),
  ('bd037d4d-6e4c-4b5b-b5f9-8098c2186156', 'e6071f53-d1b3-46cb-aabe-531f3db950d5', $$in tabel 1 zijn de percentages larven met P, Q, R en S weergegeven$$,
   $$biologie-havo-2021-ii-amerikaanse-vogelkers-context9.png$$,
   $$In tabel 1 is het percentage larven dat gevonden is op de verschillende takken, met P, Q, R en S weergegeven.$$, 'inline'),
  ('fd7277c9-fbb0-4116-af6d-a3959adc1c0a', 'e6071f53-d1b3-46cb-aabe-531f3db950d5', $$tabel 1: percentage larven na het keuze-experiment$$,
   $$biologie-havo-2021-ii-amerikaanse-vogelkers-context10.png$$,
   $$tabel 1: percentage larven na keuze-experiment gevonden op gewone lijsterbes-tak / Amerikaanse vogelkers-tak
larven verzameld op gewone lijsterbes: P / Q
larven verzameld op Amerikaanse vogelkers: R / S$$, 'inline'),
  ('1c495529-67a1-464a-8c46-4edb35cd2e14', 'e6071f53-d1b3-46cb-aabe-531f3db950d5', $$genetische verschillen tussen larven; mogelijke aanpassing aan de vogelkers$$,
   $$biologie-havo-2021-ii-amerikaanse-vogelkers-context11.png$$,
   $$Uit DNA-onderzoek bleek dat er kleine genetische verschillen zijn tussen de larven verzameld op de gewone lijsterbes en de larven verzameld op de Amerikaanse vogelkers. Het lijkt erop dat – door evolutie – aanpassing plaatsvindt aan de Amerikaanse vogelkers, waardoor er een variant van het vijfstippelig struikhaantje zou kunnen ontstaan met een voorkeur voor Amerikaanse vogelkers.$$, 'inline'),
  ('d48ac23b-4345-4beb-9d59-bcb2dc2b50dc', '01b5e24c-6418-402a-9723-a610869a08da', $$inleiding: boerderijkinderen hebben minder kans op astma$$,
   $$biologie-havo-2021-ii-boerderijstof-beschermt-tegen-astma-context1.png$$,
   $$Wetenschappers onderzoeken hoe het komt dat kinderen die opgroeien op een boerderij, minder kans hebben op astma dan andere kinderen.$$, 'inline'),
  ('cb4d24ef-c922-460f-a66d-1c499e21f700', '01b5e24c-6418-402a-9723-a610869a08da', $$astma: allergische reactie, slijmproductie en samentrekkende spiertjes$$,
   $$biologie-havo-2021-ii-boerderijstof-beschermt-tegen-astma-context2.png$$,
   $$Astma is een ongeneeslijke chronische ontsteking van de luchtwegen die meestal wordt veroorzaakt door een allergische reactie op onschuldige stoffen in de luchtwegen. Hierbij neemt de slijmproductie in de luchtwegen toe en tijdens een acute astma-aanval trekken spiertjes rond de luchtwegen samen.$$, 'inline'),
  ('36d1ca36-af77-4add-b97d-d7d73b344db3', '01b5e24c-6418-402a-9723-a610869a08da', $$medicijnen en een hormoon dat de bronchiën laat verwijden$$,
   $$biologie-havo-2021-ii-boerderijstof-beschermt-tegen-astma-context3.png$$,
   $$Astmapatiënten gebruiken medicijnen om de gevolgen van een astma- aanval te verlichten. Een daarvan laat de spiertjes rondom de luchtwegen ontspannen, waardoor de bronchiën verwijden. Er is ook een bepaald hormoon dat bronchiën laat verwijden.$$, 'inline'),
  ('304c05ef-78fe-457d-93eb-0badb2ee7517', '01b5e24c-6418-402a-9723-a610869a08da', $$hypothese endotoxinen; muizenexperiment met tabel 1$$,
   $$biologie-havo-2021-ii-boerderijstof-beschermt-tegen-astma-context4.png$$,
   $$Astma komt minder vaak voor bij kinderen die op melkveebedrijven opgroeien dan bij andere kinderen. Dit leidde tot de hypothese dat endotoxinen (bepaalde bestanddelen van bacteriën) in boerderijlucht het afweersysteem van de kinderen onderdrukken. Om deze hypothese te toetsen kregen muizen een voorbehandeling met endotoxinen. Tien dagen daarna werden ze voor een eerste keer blootgesteld aan huisstof (sensibilisering). Een week later werd een allergische reactie uitgelokt met een tweede blootstelling aan huisstof. Naast deze experimenteergroep (groep 1) waren er drie controlegroepen (groep 2, 3 en 4). Tabel 1 toont de behandeling van de vier groepen.
tabel 1 (voorbehandeling / eerste blootstelling / tweede blootstelling):
groep 1: endotoxinen / huisstof / huisstof
groep 2: endotoxinen / zoutoplossing / huisstof
groep 3: zoutoplossing / huisstof / huisstof
groep 4: zoutoplossing / zoutoplossing / huisstof$$, 'inline'),
  ('25cd06f5-6d68-4cb7-8b85-0364c64be6e0', '01b5e24c-6418-402a-9723-a610869a08da', $$na de eerste blootstelling werd een week gewacht$$,
   $$biologie-havo-2021-ii-boerderijstof-beschermt-tegen-astma-context5.png$$,
   $$Na de eerste blootstelling werd een week gewacht voor de tweede blootstelling.$$, 'inline'),
  ('a7602d05-31a9-4408-9fb9-33e348e87b0d', '01b5e24c-6418-402a-9723-a610869a08da', $$IgE-antistoffen en eosinofiele granulocyten als indicator voor allergie$$,
   $$biologie-havo-2021-ii-boerderijstof-beschermt-tegen-astma-context6.png$$,
   $$Om bij de vier groepen een allergische reactie aan te tonen werd na de tweede blootstelling het bloed onderzocht op antistoffen van het type IgE, en op bepaalde witte bloedcellen, de eosinofiele granulocyten. Toename van deze beide bloedbestanddelen is een indicator voor een allergische reactie.$$, 'inline'),
  ('9c5c9e7a-c186-4632-9d72-7651e5bcdd97', '01b5e24c-6418-402a-9723-a610869a08da', $$volgorde van de staven komt niet overeen met tabel 1$$,
   $$biologie-havo-2021-ii-boerderijstof-beschermt-tegen-astma-context7.png$$,
   $$De resultaten van het bloedonderzoek zijn weergegeven in afbeelding 1. De volgorde van de staven in afbeelding 1 komt niet overeen met de volgorde van de groepen in tabel 1.$$, 'inline'),
  ('1a17069f-0744-41c0-a144-2aa018549227', '01b5e24c-6418-402a-9723-a610869a08da', $$afbeelding 1: eosinofiele granulocyten en IgE-antistoffen per groep P t/m S$$,
   $$biologie-havo-2021-ii-boerderijstof-beschermt-tegen-astma-context8.png$$,
   $$afbeelding 1: twee staafdiagrammen voor de groepen P, Q, R en S: links eosinofiele granulocyten per mL (0 tot 1,5·10⁶), rechts de relatieve hoeveelheid IgE-antistoffen (0 tot 1,5); in beide diagrammen is staaf Q veruit het hoogst (ongeveer 1,2·10⁶ resp. 1,0), P, R en S zijn laag$$, 'inline'),
  ('42671de9-bb85-49cb-9e1a-224edce41508', '01b5e24c-6418-402a-9723-a610869a08da', $$blootstelling aan endotoxinen verminderde de allergische reactie$$,
   $$biologie-havo-2021-ii-boerderijstof-beschermt-tegen-astma-context9.png$$,
   $$Uit het onderzoek bleek inderdaad dat bij blootstelling aan endotoxinen de allergische reactie verminderd was.$$, 'inline');

